function effectiveGroup(g,item,cup){let o=item?.optionOverrides?.[g.id]||{mode:'inherit'},mode=o.mode||'inherit',match=v=>g.choices.find(c=>c.label===v||c.label.startsWith(v+'（')||c.label.startsWith(v+' '));if(mode==='inherit'&&g.role==='sweetness'&&item?.fixedSugar){const c=match(item.fixedSugar);if(c){mode='fixed';o={choiceIds:[c.id]};}}if(mode==='inherit'&&g.role==='temperature'&&item?.fixedIce){const c=match(item.fixedIce);if(c){mode='fixed';o={choiceIds:[c.id]};}}if(mode==='disabled')return null;let cs=g.choices||[];if(['custom','fixed'].includes(mode))cs=cs.filter(c=>(o.choiceIds||[]).includes(c.id));const ids=cup?.optionChoiceIds?.[g.id];if(Array.isArray(ids))cs=cs.filter(c=>ids.includes(c.id));if(g.role==='temperature'&&cup?.size){const hotSizes=g.hotCupSizes||o.hotCupSizes||item?.hotCupSizes;if(Array.isArray(hotSizes)&&hotSizes.length){cs=cs.filter(c=>variantTemperature(c)!=='熱'||hotSizes.includes(cup.size));}if(item?.variants){const av=new Set(item.variants.filter(v=>v.size===cup.size).map(v=>v.temp));if(av.size)cs=cs.filter(c=>av.has(variantTemperature(c)));}}if(g.role==='topping'&&Array.isArray(item?.allowedToppings)){if(!item.allowedToppings.length)return null;cs=cs.filter(c=>item.allowedToppings.includes(c.label));}if(!cs.length)return null;return {...clone(g),mode,required:mode==='fixed'?false:g.required,choices:cs,fixedChoiceId:mode==='fixed'?(o.fixedChoiceId||cs[0].id):''};}
function effectiveGroups(b,i,c){const defaults=groupsForBrand(b),customs=i?.optionGroups||[],out=defaults.map(g=>{const custom=customs.find(x=>x.id===g.id);if(custom&&custom.inheritDefault===false)return effectiveGroup({...g,...clone(custom),choices:Array.isArray(custom.choices)?custom.choices:[]},i,c);if(custom&&custom.inheritDefault===true)return effectiveGroup({...g,name:custom.name||g.name,required:custom.required??g.required,kind:custom.kind||g.kind,maxChoices:custom.maxChoices,hotCupSizes:custom.hotCupSizes,hotSurcharge:custom.hotSurcharge},i,c);return effectiveGroup(g,i,c);}).filter(Boolean);for(const custom of customs.filter(x=>!defaults.some(g=>g.id===x.id)&&x.inheritDefault===false)){const group=effectiveGroup({...clone(custom),choices:Array.isArray(custom.choices)?custom.choices:[]},i,c);if(group)out.push(group);}return out;}
